import React, { Component } from 'react';
import { Card, CardBody, CardHeader, Col,Row, Table,Button} from 'reactstrap';
import {fetchAllPosDetails} from '../../actions/merchant';
import {connect} from 'react-redux';
import {bindActionCreators} from 'redux';
import moment from 'moment';
// import Moment from 'react-moment';
import Pagination2 from "react-js-pagination";
import {FormattedMessage
    // ,FormattedDate,
} from 'react-intl';
import Moment from 'react-moment';
import 'react-datepicker/dist/react-datepicker.css';

import 'react-dates/initialize';
import { 
    // DateRangePicker, 
    SingleDatePicker} from 'react-dates';
import 'react-dates/lib/css/_datepicker.css';

class MerchantPayment extends Component{
    constructor(props){
        super(props);
        this.state = {
            showModal:false,
            processorCreated:false,
            showUpdateModal:false,
            startDate: moment(),
            activePage:1,
        }
        this.handlePageChange= this.handlePageChange.bind(this);
    }


    
    componentDidMount(){
        
        this.props.fetchAllPosDetails(null)
    }

    submitDate=()=>{
        
        // console.log(moment(this.state.startDate).format());
        let date1 = moment(this.state.startDate).format();

        debugger;
        
        if(date1.includes("T")){
            let extract = date1.split("T");
            date1 = extract[0];
            this.setState({paramsDate:date1});
         }
        this.props.fetchAllPosDetails(date1);
        
    }

    handlePageChange = (pageNumber) => {
        let pageNumberParam = pageNumber - 1;
        this.props.fetchChannelLogsPaginated(pageNumberParam);
        this.setState({activePage: pageNumber});
        
    }

    onSubmit = (values) =>{
        this.props.createProcessor(values);
       this.closeModal();
    }

    updateProcessor = (id) => {
        this.setState({ showUpdateModal: !this.state.showUpdateModal });
        this.props.getOneProcessor(id);
    }

    closeUpdateModal = () => {
        this.setState({ showUpdateModal: !this.state.showUpdateModal });
    }

    onSubmitUpdate = (values) => {
        this.props.updateProcessor(values);
        this.closeUpdateModal();
    }
    toggle = () => {
        this.setState({ showModal: !this.state.showModal });
    }
    closeModal = () => {
        this.setState({ showModal: !this.state.showModal });
    }
    deleteProcessor = (id) => {
        this.props.deleteProcessor(id);
    }
    
    render(){
        console.log('Props here is ',this.props);
        return(
            <div className="animated fadeIn">
                
                <div style={{'marginBottom':'20px','display':'flex',justifyContent:'flex-end'}}>
                    <SingleDatePicker
                        showDefaultInputIcon={true}
                        date={this.state.startDate} // momentPropTypes.momentObj or null
                        onDateChange={startDate => this.setState({ startDate })} // PropTypes.func.isRequired
                        focused={this.state.focused} // PropTypes.bool
                        onFocusChange={({ focused }) => this.setState({ focused })} // PropTypes.func.isRequired
                        id="your_unique_id" // PropTypes.string.isRequired,
                        isOutsideRange={() => false}
                        numberOfMonths={1}
                    />
                    <input type="text" placeholder="Enter Merchant Id"/>
                    <Button size="sm" className="btn " onClick={this.submitDate} color="primary" style={{fontSize:'15px',marginLeft:'10px'}}> <FormattedMessage id="app.submit" defaultMessage="Submit"/></Button>
                </div>
                
                <Row>
                    <Col>
                        <Card>
                            <CardHeader>
                                <i className="fa fa-money"></i> Merchant Payment
                            </CardHeader>
                            <CardBody>
                                <Table hover bordered striped responsive size="sm" className="table-outline mb-0 d-sm-table">
                                    <thead className="thead-light">
                                        <tr>
                                            <th>
                                                Merchant Id
                                            </th>
                                            <th>
                                                Merchant Name
                                            </th>
                                            <th>
                                                Batch Date
                                            </th>
                                            <th>
                                                Affiliate Name
                                            </th>
                                            <th>
                                                Total Amount
                                            </th>  
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {  this.props.merchants.posDetailsList? [
                                                this.props.merchants.posDetailsList.data.content.length > 0 ?  this.props.merchants.posDetailsList.data.content.map((item,index) => (
                                                    <tr key={index+1}>
                                                        <td> 
                                                            <a href={"#/merchant-payments/"+item.merchantId+"/details"}>{item.merchantId}</a>
                                                        </td>
                                                        <td>
                                                            {item.merchantName}
                                                        </td>
                                                        <td>
                                                            <Moment format="LL">{item.batchDate}</Moment>
                                                        </td>
                                                        <td>
                                                            {item.affiliateName}
                                                        </td>
                                                        <td>
                                                            {Number(item.totalAmount).toLocaleString()}
                                                        </td>
                                                    </tr>
                                                )):<tr><td colSpan="5"><p className="text-center text-danger">There are no merchant payment files at the moment.</p></td></tr>
                                            ]
                                            : [
                                                ''
                                            ]
                                        }
                                    </tbody>
                                </Table>
                            
                                {this.props.merchants.posDetailsList?<nav>
                                <Pagination2
                                    activePage={this.state.activePage}
                                    itemsCountPerPage={10}
                                    totalItemsCount={this.props.merchants.posDetailsList.data.totalElements?this.props.merchants.posDetailsList.data.totalElements:null}
                                    pageRangeDisplayed={20} 
                                    onChange={this.handlePageChange}
                                />
                                </nav>:'' }
                            </CardBody>
                        </Card>
                    </Col>
                </Row>
            </div>
        )
    }
}


const mapStateToProps = (state) => {
    console.log('State is ',state);
    return {
       merchants:state.merchants
    }
  }
  
  const mapDispatchToProps= (dispatch) => {
    return bindActionCreators({
        fetchAllPosDetails
    },dispatch)
  }
  
  export default connect(mapStateToProps,mapDispatchToProps)(MerchantPayment);